package com.androidhit.lumadrift.qa.commerce112;
import android.app.*;import android.content.*;import android.content.pm.PackageInfo;import android.accessibilityservice.AccessibilityServiceInfo;import android.graphics.*;import android.os.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Predicate;
/** Guest-only normal visible navigation. No login, ad, age, purchase or simulation controls are invoked. */
public final class CommerceInstrumentation extends Instrumentation {
 private static final String TARGET="com.androidhit.lumadrift";
 private static final String[] SETTINGS={"Settings","Réglages","Paramètres","Einstellungen","Ajustes","Definições","Impostazioni"},LANG={"en","fr","de","es","pt","it"},NAMES={"English","Français","Deutsch","Español","Português","Italiano"},SHOPS={"Shop","Boutique","Shop","Tienda","Loja","Negozio"},HOMES={"Home","Accueil","Start","Inicio","Início","Home"},WALLETS={"View wallet","Voir le portefeuille","Guthaben ansehen","Ver monedero","Ver carteira","Vedi portafoglio"},TITLES={"Little wonders","Petites merveilles","Kleine Wunder","Pequeñas maravillas","Pequenas maravilhas","Piccole meraviglie"},OWNED={"In your collection","Dans ta collection","In deiner Sammlung","En tu colección","Na tua coleção","Nella tua collezione"},SKIP={"Play at my pace","Jouer à mon rythme","In meinem Tempo spielen","Jugar a mi ritmo","Jogar no meu ritmo","Gioca al tuo ritmo","Later","Plus tard","Später","Más tarde","Mais tarde","Più tardi"};
 private Bundle args;private UiAutomation ui;private File out;private int count;private final JSONArray checks=new JSONArray(),actions=new JSONArray(),captures=new JSONArray();
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b==null?new Bundle():b;start();}
 @Override public void onStart(){new Thread(()->{boolean passed=false;Bundle result=new Bundle();try{
  check(TARGET.equals(getTargetContext().getPackageName()),"Exact production target");ui=getUiAutomation();AccessibilityServiceInfo service=ui.getServiceInfo();service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS;ui.setServiceInfo(service);
  out=new File(getTargetContext().getExternalFilesDir(null),"v112-commerce-native");if(!out.exists()&&!out.mkdirs())throw new IOException("Output unavailable");
  PackageInfo info=getTargetContext().getPackageManager().getPackageInfo(TARGET,0);check(args.getString("expectedVersion").equals(info.versionName)&&Integer.parseInt(args.getString("expectedCode"))==info.versionCode,"Exact frozen version/code loaded");
  check(!getTargetContext().getSharedPreferences("luma_commerce_privacy_v1",0).getBoolean("explicit_ads_opt_in",false),"Original profile has no explicit advertising opt-in");
  Intent launch=new Intent().setClassName(TARGET,"com.androidhit.lumadrift.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivitySync(launch);SystemClock.sleep(900);
  if(has(x->Arrays.asList(SKIP).contains(x),true))click(x->Arrays.asList(SKIP).contains(x),false);
  for(int locale=0;locale<LANG.length;locale++){
   final int i=locale;click(x->Arrays.asList(SETTINGS).contains(x),true);click(x->x.equals(NAMES[i]),true);back();top();
   Map<String,?> economic=economic();capture("home-"+LANG[i]);click(x->x.equals(SHOPS[i]),true);top();click(x->x.equals("LumaGold"),false);capture("shop-gold-"+LANG[i]);
   click(x->x.startsWith(WALLETS[i]),true);waitFor(x->x.equals(TITLES[i]),false);SystemClock.sleep(600);capture("commerce-hero-"+LANG[i]);
   check(has(x->x.equals("LumaGold"),false)&&has(x->x.toLowerCase(Locale.ROOT).contains("lumagold")&&!x.equals("LumaGold"),false),"Actual "+LANG[i]+" premium wallet has named currency and unknown accessible state");
   check(has(x->x.equals("LumaCoins"),false),"Actual "+LANG[i]+" earned currency distinct label");
   check(!has(x->x.matches("LumaGold[: ·]*0"),false),"Actual "+LANG[i]+" guest unknown balance is not fabricated zero");
   seek(x->Arrays.asList("Account & purchases","Compte et achats","Konto & Käufe","Cuenta y compras","Conta e compras","Account e acquisti").contains(x),false,5);capture("commerce-account-"+LANG[i]);
   seek(x->x.startsWith("Miko ·"),false,14);AccessibilityNodeInfo disabled=waitAny(x->x.startsWith("Miko ·"));check(!disabled.isEnabled(),"Actual "+LANG[i]+" cosmetic spending disabled without configured server/account balance");disabled.recycle();capture("commerce-offers-"+LANG[i]);
   // Reach the optional privacy section through the actual ScrollView; do not alter any control.
   AccessibilityNodeInfo toggle=null;for(int s=0;s<55&&toggle==null;s++){toggle=findAny(x->x.getClassName()!=null&&x.getClassName().toString().equals("android.widget.Switch"));if(toggle==null)scroll(true);}
   check(toggle!=null&&!toggle.isChecked(),"Actual "+LANG[i]+" advertising consent remains visibly off");if(toggle!=null)toggle.recycle();capture("commerce-consent-"+LANG[i]);
   check(!getTargetContext().getSharedPreferences("luma_commerce_privacy_v1",0).getBoolean("explicit_ads_opt_in",false),"Actual "+LANG[i]+" navigation never opts into advertising");check(economic.equals(economic()),"Actual "+LANG[i]+" wallet browsing changes no coins, inventory, equipment or progression");back();top();click(x->x.equals(HOMES[i]),true);
  }
  passed=true;result.putString("summary","PASS "+count+" native commerce checks");
 }catch(Throwable failure){result.putString("failure",failure.toString());try{if(out!=null){capture("failure");StringWriter w=new StringWriter();failure.printStackTrace(new PrintWriter(w));write("failure.txt",w.toString());}}catch(Throwable ignored){}}
 finally{try{if(out!=null){write("actions.json",actions.toString(2));write("report.json",new JSONObject().put("passed",passed).put("checkCount",count).put("checks",checks).put("captures",captures).put("package",TARGET).put("scope","Visible Main to Shop to LumaGold to Commerce navigation in six languages; no login/ad/age/purchase/simulation/refund control").toString(2));}}catch(Throwable ignored){}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}},"luma-commerce-native").start();}
 private Map<String,?> economic(){Map<String,Object> values=new TreeMap<>();for(var e:getTargetContext().getSharedPreferences("luma_drift_save_v1",0).getAll().entrySet())if(!e.getKey().equals("language")&&!e.getKey().startsWith("tutorial_"))values.put(e.getKey(),e.getValue());return values;}
 private List<AccessibilityNodeInfo> nodes(){if(Build.VERSION.SDK_INT>=33)ui.clearCache();List<AccessibilityNodeInfo> list=new ArrayList<>();AccessibilityNodeInfo root=ui.getRootInActiveWindow();if(root==null)return list;ArrayDeque<AccessibilityNodeInfo> queue=new ArrayDeque<>();queue.add(root);while(!queue.isEmpty()&&list.size()<1000){AccessibilityNodeInfo n=queue.remove();list.add(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)queue.add(child);}}return list;}
 private String name(AccessibilityNodeInfo n){CharSequence s=n.getContentDescription();if(s==null||s.length()==0)s=n.getText();return s==null?"":s.toString();}
 private AccessibilityNodeInfo findAny(Predicate<AccessibilityNodeInfo> predicate){AccessibilityNodeInfo found=null;for(AccessibilityNodeInfo n:nodes()){Rect bounds=new Rect();n.getBoundsInScreen(bounds);if(found==null&&n.isVisibleToUser()&&bounds.width()>0&&bounds.height()>0&&predicate.test(n))found=AccessibilityNodeInfo.obtain(n);n.recycle();}return found;}
 private AccessibilityNodeInfo find(Predicate<String> p,boolean click){return findAny(n->(!click||n.isClickable()&&n.isEnabled())&&p.test(name(n)));}
 private boolean has(Predicate<String> p,boolean click){AccessibilityNodeInfo n=find(p,click);if(n==null)return false;n.recycle();return true;}
 private AccessibilityNodeInfo waitFor(Predicate<String> p,boolean click)throws Exception{for(int i=0;i<40;i++){AccessibilityNodeInfo n=find(p,click);if(n!=null)return n;SystemClock.sleep(100);}throw new AssertionError("Missing node; visible="+labels());}
 private AccessibilityNodeInfo waitAny(Predicate<String> p)throws Exception{return waitFor(p,false);}
 private String labels(){List<String> values=new ArrayList<>();for(AccessibilityNodeInfo n:nodes()){values.add(name(n));n.recycle();}return values.toString();}
 private void click(Predicate<String> p,boolean seek)throws Exception{if(seek)seek(p,true,25);AccessibilityNodeInfo n=waitFor(p,true);String label=name(n);if(!allowed(label))throw new AssertionError("Control outside navigation allowlist: "+label);Rect bounds=new Rect();n.getBoundsInScreen(bounds);boolean done=n.performAction(AccessibilityNodeInfo.ACTION_CLICK);n.recycle();if(!done)throw new AssertionError("SDK click rejected "+label);actions.put(new JSONObject().put("label",label).put("bounds",bounds.toShortString()).put("action","native accessibility ACTION_CLICK"));SystemClock.sleep(220);}
 private boolean allowed(String label){for(String[] group:new String[][]{SETTINGS,NAMES,SHOPS,HOMES,SKIP})if(Arrays.asList(group).contains(label))return true;if(label.equals("LumaGold"))return true;for(String wallet:WALLETS)if(label.startsWith(wallet))return true;return false;}
 private void seek(Predicate<String> p,boolean click,int limit)throws Exception{for(int i=0;i<limit;i++){if(has(p,click))return;scroll(true);}if(!has(p,click))throw new AssertionError("Cannot find requested visible node; labels="+labels());}
 private boolean scroll(boolean forward){AccessibilityNodeInfo node=findAny(n->n.isScrollable());if(node==null)node=find(x->x.startsWith("Luma Drift · "),false);if(node==null)return false;boolean done=node.performAction(forward?AccessibilityNodeInfo.ACTION_SCROLL_FORWARD:AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD);node.recycle();SystemClock.sleep(120);return done;}
 private void top(){for(int i=0;i<70;i++)if(!scroll(false))break;}
 private void back(){ui.performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);SystemClock.sleep(220);}
 private void capture(String name)throws Exception{Bitmap bitmap=ui.takeScreenshot();if(bitmap==null)throw new IOException("Screenshot unavailable");try(OutputStream stream=new FileOutputStream(new File(out,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}finally{bitmap.recycle();}captures.put(name);JSONArray tree=new JSONArray();for(AccessibilityNodeInfo node:nodes()){Rect bounds=new Rect();node.getBoundsInScreen(bounds);tree.put(new JSONObject().put("label",name(node)).put("class",String.valueOf(node.getClassName())).put("bounds",bounds.toShortString()).put("clickable",node.isClickable()).put("enabled",node.isEnabled()).put("checked",node.isChecked()).put("visible",node.isVisibleToUser()));node.recycle();}write(name+"-nodes.json",tree.toString(2));}
 private void check(boolean value,String message)throws Exception{count++;checks.put(new JSONObject().put("pass",value).put("message",message));if(!value)throw new AssertionError(message);Bundle status=new Bundle();status.putString("stream","PASS "+message+"\n");sendStatus(0,status);}
 private void write(String name,String value)throws Exception{try(OutputStream stream=new FileOutputStream(new File(out,name))){stream.write(value.getBytes(StandardCharsets.UTF_8));}}
}
